{"sql": "CREATE TABLE \"TESTAPP_BUS\" (\"ID\" NUMBER(19,0) GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, \"PLATE\" NCLOB,  PRIMARY KEY (\"ID\") USING INDEX  ENABLE)"}
{"sql": "CREATE TABLE \"DJANGO_MIGRATIONS\" (\"ID\" NUMBER(19,0) GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, \"APP\" NVARCHAR2(255), \"NAME\" NVARCHAR2(255), \"APPLIED\" TIMESTAMP (6) NOT NULL ENABLE,  PRIMARY KEY (\"ID\") USING INDEX  ENABLE)"}
